function createQuestion(prompt, correctAnswer, ...distractors) {
	const options = [correctAnswer, ...distractors];
	let hash = 0;
	for (const character of prompt) hash = (hash * 31 + character.charCodeAt(0)) >>> 0;
	const correctIndex = hash % options.length;
	[options[0], options[correctIndex]] = [options[correctIndex], options[0]];
	return {
		prompt,
		options,
		answer: correctIndex,
		explanation: correctAnswer,
	};
}

function createQuiz(number, title, questions) {
	if (questions.length !== 20) {
		throw new Error(`Module ${number} quiz must contain exactly 20 questions.`);
	}
	return { number, title, questions };
}

